return [
  { json: { url: "https://t.me/s/v2rayng3" } },
  { json: { url: "https://t.me/s/V2ray_Alpha" } },
  { json: { url: "https://t.me/s/v2rayirane" } }
];

const items = $input.all();
let allHtml = items.map(item => item.json?.data || '').join(' ');

// Decode HTML entities so config strings do not keep &amp; etc.
let prev;
do {
  prev = allHtml;
  allHtml = allHtml
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x2F;/g, '/');
} while (allHtml !== prev);

const PROTOCOL_REGEX = /(vless:\/\/[^\s<>"\'\]]+|vmess:\/\/[^\s<>"\'\]]+|hysteria2?:\/\/[^\s<>"\'\]]+|hy2:\/\/[^\s<>"\'\]]+|trojan:\/\/[^\s<>"\'\]]+|ss:\/\/[^\s<>"\'\]]+)/gi;

const blocks = allHtml.split('tgme_widget_message_text');
const parsedConfigs = [];

for (const block of blocks) {
  const links = block.match(PROTOCOL_REGEX);
  if (!links) continue;

  const rawText = block.replace(/<[^>]*>?/gm, ' ');

  // Flag extraction
  const flagMatch = rawText.match(/[\uD83C][\uDDE6-\uDDFF][\uD83C][\uDDE6-\uDDFF]/);
  const flag = flagMatch ? flagMatch[0] : '🌐';

  // Location extraction
  let location = 'جهانی';
  let countryCode = 'ALL';
  const locMatch = rawText.match(/(آلمان|هلند|فنلاند|آمریکا|انگلیس|فرانسه|سوئد|ترکیه|روسیه|امارات|سنگاپور|کانادا|لهستان|سوئیس|ایتالیا)/);
  if (locMatch) {
    location = locMatch[1];
    const codeMap = {
      'آلمان': 'DE', 'هلند': 'NL', 'فنلاند': 'FI', 'آمریکا': 'US', 'انگلیس': 'GB',
      'فرانسه': 'FR', 'سوئد': 'SE', 'ترکیه': 'TR', 'روسیه': 'RU', 'امارات': 'AE',
      'سنگاپور': 'SG', 'کانادا': 'CA', 'لهستان': 'PL', 'سوئیس': 'CH', 'ایتالیا': 'IT'
    };
    countryCode = codeMap[location] || 'ALL';
  }

  // Operator extraction
  let operator = 'all';
  if (rawText.match(/(mci|همراه|mci_|@mci|#mci)/i)) operator = 'mci';
  else if (rawText.match(/(irancell|ایرانسل|mtn|#mtn)/i)) operator = 'irancell';
  else if (rawText.match(/(rightel|رایتل|#rightel)/i)) operator = 'rightel';
  else if (rawText.match(/(wifi|وایفای|مخابرات|شاتل|زیتل|#wifi)/i)) operator = 'wifi';

  for (const link of links) {
    let protocol = 'vless';
    if (link.startsWith('vmess://')) protocol = 'vmess';
    else if (link.startsWith('hysteria') || link.startsWith('hy2')) protocol = 'hysteria2';
    else if (link.startsWith('trojan://')) protocol = 'trojan';
    else if (link.startsWith('ss://')) protocol = 'ss';

    let name = `${flag} ${protocol.toUpperCase()} - ${location}`;
    if (operator !== 'all') {
      const opName = operator === 'mci' ? 'همراه اول' : operator === 'irancell' ? 'ایرانسل' : operator === 'rightel' ? 'رایتل' : 'وای‌فای';
      name += ` (${opName})`;
    }

    parsedConfigs.push({
      config_string: link,
      protocol: protocol,
      name: name,
      operator: operator,
      location: location,
      flag: flag,
      country_code: countryCode,
      quality: 'good',
      is_official: true,
      is_active: true,
      is_vip: false
    });
  }
}

// Deduplicate configs by config_string
const seen = new Set();
const unique = [];
for (const c of parsedConfigs) {
  if (!seen.has(c.config_string)) {
    seen.add(c.config_string);
    unique.push(c);
  }
}

return unique.slice(0, 6).map(c => ({ json: c }));

const items = $input.all();
if (!items || items.length === 0) {
  return [];
}
// Filter out any items without config_string just in case
const validItems = items.filter(i => i.json && i.json.config_string);
return validItems.slice(0, 3);
